all_pkg = pd.read_sql("SELECT Name, Version, VersionInfo FROM packageinfo WHERE System='NPM'", pkg_conn)
print(all_pkg.shape)
# Parse VersionInfo
def parse_vi(s):
    try:
        d = json.loads(s)
        return d.get('IsRelease'), d.get('Ordinal')
    except Exception:
        return None, None

all_pkg[['IsRelease','Ordinal']] = all_pkg['VersionInfo'].apply(lambda x: pd.Series(parse_vi(x)))
print(all_pkg[['IsRelease','Ordinal']].describe(include='all'))
print(all_pkg['IsRelease'].value_counts(dropna=False))

