# Now parse stars from Project_Information
def parse_stars(text):
    if text is None:
        return None
    # patterns covering: "X stars", "stars count of X", "star count of X"
    pats = [
        r'([\d,]+)\s+stars',
        r'stars\s+count\s+of\s+([\d,]+)',
        r'star\s+count\s+of\s+([\d,]+)',
    ]
    for p in pats:
        m = re.search(p, text)
        if m:
            return int(m.group(1).replace(',', ''))
    return None

pinfo['stars'] = pinfo['Project_Information'].apply(parse_stars)
print("with stars:", pinfo['stars'].notna().sum(), "/", len(pinfo))
print(pinfo[pinfo['stars'].isna()]['Project_Information'].head(10).tolist())

